/// <summary>
/// Conversations run by the server, shown in the game's dialogue list with an optional line above
/// it. A page is { line?, onRight?, options: [{ id, text, enabled? }] }, with 1 to 8 rows and
/// unique ids. `enabled: false` only greys a row, so check costs in your handler. A player has one
/// conversation at a time. Events are dialogueChoice(session, player, optionId) and
/// dialogueClosed(session, player, reason), where the reason is 0 for Dialogue.close, 1 if the
/// player backed out, 2 if another conversation replaced it, and 3 if interrupted because the
/// player left, was knocked out or went out of reach, it timed out, or the NPC died. While a
/// conversation is shown, the game starts none of its own for that player, so a nearby NPC's line
/// does not end it. (Server only.)
/// </summary>
public static class Dialogue
{

    /// <summary>
    /// Opens a conversation and returns the session id. Returns 0 for an unusable page, or a player who
    /// is gone or still loading. (Server only.)
    /// </summary>
    /// <param name="player">The player.</param>
    /// <param name="page">The first page.</param>
    /// <param name="options">Optional: `npc`, an Npc or its id, is the speaker, and ends the session on dying or disappearing. `npc` or `position`, with `radius` (default 4 m), ends it when the player walks away. `timeout` in seconds, 0 for none, ends it if a page gets no choice for that long.</param>
    /// <returns>number</returns>
    public static double Open(object? player, object? page, object? options = null) => Sdk.Call<double>("characters", "Dialogue", "open", player, page, Sdk.Optional(options));

    /// <summary>
    /// Shows the next page. Returns false if the session has ended or the page is unusable. (Server
    /// only.)
    /// </summary>
    /// <param name="session">The session id.</param>
    /// <param name="page">The new page.</param>
    /// <returns>boolean</returns>
    public static bool Update(object? session, object? page) => Sdk.Call<bool>("characters", "Dialogue", "update", session, page);

    /// <summary>
    /// Ends the conversation with reason 0. Returns false if it has already ended. (Server only.)
    /// </summary>
    /// <param name="session">The session id.</param>
    /// <returns>boolean</returns>
    public static bool Close(object? session) => Sdk.Call<bool>("characters", "Dialogue", "close", session);

    /// <summary>
    /// The player's conversation, or 0. (Server only.)
    /// </summary>
    /// <param name="player">The player.</param>
    /// <returns>number</returns>
    public static double ActiveSession(object? player) => Sdk.Call<double>("characters", "Dialogue", "activeSession", player);
}

/// <summary>
/// Shops stored on the server and traded through the game's shop screen. A vendor has a shelf of
/// priced rows, a list of what it pays for players' items, and a purse. Prices are in units of the
/// game's money item. The client only estimates. When the player confirms, the server recalculates
/// from its own data and either completes the trade or refuses it, for example because stock
/// changed, someone lacks money, or there is no space. A player can use one vendor at a time. A
/// vendor created with `haggle` haggles in the game's own haggle with its NPC, and the server
/// answers every offer. Events are vendorTrade(vendor, player, bought, sold, balance, haggled),
/// vendorHaggle(vendor, player, basket, offered) and vendorClosed(vendor, player, reason), where
/// the reason is 0 closed by the player, 1 by the server, 2 replaced by another vendor, 3 failed to
/// open, or 4 the player disconnected. (Server only.)
/// </summary>
public static class Vendor
{

    /// <summary>
    /// Creates a vendor and returns its id. (Server only.)
    /// </summary>
    /// <param name="options">Optional: `name`; `purse`, in money units, where none means it never runs out; `buys`, default true, whether it buys players' items; `haggle`, true or { tolerance, rounds }, to haggle in the game's haggle when opened with an NPC: `tolerance` is the most the vendor gives off the list price as a share of the basket's value (0 to 0.35, default 0.1), `rounds` the offers it hears before refusing (1 to 20, default 5). Without vendorHaggle answers the vendor follows the game's rule, with the player's Speech.</param>
    /// <returns>number</returns>
    public static double Create(object? options = null) => Sdk.Call<double>("characters", "Vendor", "create", Sdk.Optional(options));

    /// <summary>
