    /// <returns>boolean</returns>
    public static bool Destroy(object? vendor) => Sdk.Call<bool>("characters", "Vendor", "destroy", vendor);

    /// <summary>
    /// Replaces the shelf, with up to 128 rows. (Server only.)
    /// </summary>
    /// <param name="vendor">The vendor's id.</param>
    /// <param name="rows">[{ item, amount, price, metadata? }], with the price per unit.</param>
    /// <returns>boolean</returns>
    public static bool SetShelf(object? vendor, object? rows) => Sdk.Call<bool>("characters", "Vendor", "setShelf", vendor, rows);

    /// <summary>
    /// Sets what the vendor pays per unit for players' items, up to 128 rows. It does not buy items
    /// left out. (Server only.)
    /// </summary>
    /// <param name="vendor">The vendor's id.</param>
    /// <param name="rows">[{ item, price }].</param>
    /// <returns>boolean</returns>
    public static bool SetOffers(object? vendor, object? rows) => Sdk.Call<bool>("characters", "Vendor", "setOffers", vendor, rows);

    /// <summary>
    /// Sets how much money the vendor has. null means unlimited. (Server only.)
    /// </summary>
    /// <param name="vendor">The vendor's id.</param>
    /// <param name="purse">Money units, or null.</param>
    /// <returns>boolean</returns>
    public static bool FillPurse(object? vendor, object? purse) => Sdk.Call<bool>("characters", "Vendor", "fillPurse", vendor, purse);

    /// <summary>
    /// The vendor's money, or null for an endless purse. (Server only.)
    /// </summary>
    /// <param name="vendor">The vendor's id.</param>
    /// <returns>number | null</returns>
    public static double? PurseOf(object? vendor) => Sdk.Call<double?>("characters", "Vendor", "purseOf", vendor);

    /// <summary>
    /// Opens the shop screen for a player and returns the session id, or 0 if the vendor or player is
    /// gone. (Server only.)
    /// </summary>
    /// <param name="vendor">The vendor's id.</param>
    /// <param name="player">The player.</param>
    /// <param name="npc">The NPC selling, and the session ends when it dies or disappears. The game's shop screen needs a trader, so with no living NPC near the player, the session opens and ends at once without showing the screen.</param>
    /// <returns>number</returns>
    public static double Open(object? vendor, object? player, object? npc) => Sdk.Call<double>("characters", "Vendor", "open", vendor, player, npc);

    /// <summary>
    /// Closes a session's screen. Returns false if the session has ended. (Server only.)
    /// </summary>
    /// <param name="session">The session id.</param>
    /// <returns>boolean</returns>
    public static bool Close(object? session) => Sdk.Call<bool>("characters", "Vendor", "close", session);

    /// <summary>
    /// The player's open session id, or 0. (Server only.)
    /// </summary>
    /// <param name="player">The player.</param>
    /// <returns>number</returns>
    public static double ActiveSession(object? player) => Sdk.Call<double>("characters", "Vendor", "activeSession", player);

    /// <summary>
    /// A session's vendor, or 0. (Server only.)
    /// </summary>
    /// <param name="session">The session id.</param>
    /// <returns>number</returns>
    public static double ShopOf(object? session) => Sdk.Call<double>("characters", "Vendor", "shopOf", session);
}

