/// <summary>
/// Makes the local player follow another player or a server NPC with the game's follow action. One
/// follow is queued or running at a time. It ends with Follow.stop(), a movement key, the target
/// going, the game ending it, or the resource stopping. Events are followStarted and followStopped.
/// (Client only.)
/// </summary>
public static class Follow
{

    /// <summary>
    /// Who can be followed: players and NPCs within 20 m. (Client only.)
    /// </summary>
    /// <returns>{ id, kind: 'player' | 'npc', name, position }[]</returns>
    public static JsValue Targets() => Sdk.Call<JsValue>("characters", "Follow", "targets");

    /// <summary>
    /// Whether a follow could start now, by the game's checks and the start distance. (Client only.)
    /// </summary>
    /// <param name="target">A Player, an entry from targets(), or a network id.</param>
    /// <returns>boolean</returns>
    public static bool CanStart(object? target) => Sdk.Call<bool>("characters", "Follow", "canStart", target);

    /// <summary>
    /// Queues a follow. followStarted fires when the game's action is running. (Client only.)
    /// </summary>
    /// <param name="target">A Player, an entry from targets(), or a network id.</param>
    /// <param name="options">Optional. `hint`: false hides the "Stop following" prompt. `playerCanStop`: false makes the stop and movement keys do nothing, so only Follow.stop() and automatic endings stop it. Both are true by default. `pace`: 'walk', the default, where the follower walks even behind a running leader, or 'run', where the follower runs too. `distance`: how close to keep, 0.5 to 10 m. With 0, the default, the game stops at 1.5 m but sets off again only at 5 m, so a follower trails 5 to 8 m behind a walking leader. With a distance, the follower jogs when a metre beyond it, unless cuffed.</param>
    /// <returns>boolean</returns>
    public static bool Start(object? target, object? options = null) => Sdk.Call<bool>("characters", "Follow", "start", target, Sdk.Optional(options));

    /// <summary>
    /// Who is being followed. Null if nobody, or if a follow is only queued; see isPending. (Client
    /// only.)
    /// </summary>
    /// <returns>object | null</returns>
    public static JsValue GetTarget() => Sdk.Call<JsValue>("characters", "Follow", "getTarget");

    /// <summary>
    /// Whether a follow is queued but the game's action has not started. (Client only.)
    /// </summary>
    /// <returns>boolean</returns>
    public static bool IsPending() => Sdk.Call<bool>("characters", "Follow", "isPending");

    /// <summary>
    /// Ends the follow with the reason 'script'. (Client only.)
    /// </summary>
    public static JsValue Stop() => Sdk.Call<JsValue>("characters", "Follow", "stop");
